SELECT c.c_customer_id, wp.wp_type, SUM(wr.wr_return_amt) AS total_return_amount, (SELECT wr2.wr_return_quantity FROM web_returns wr2 WHERE wr2.wr_returned_date_sk = 2451767 LIMIT 1) AS sample_return_quantity FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk JOIN web_returns wr ON wr.wr_order_number = ws.ws_order_number WHERE wp.wp_type = 'welcome                                           ' GROUP BY c.c_customer_id, wp.wp_type HAVING COUNT(DISTINCT ws.ws_order_number) > 424892
